import re

def parse_json(json_str):
    # Check for syntax errors
    if not re.match(r'^[\{\[].*[\}\]]$', json_str):
        raise SyntaxError("Invalid JSON syntax")

    # Initialize the stack for parsing
    stack = []
    current_value = None
    current_type = None
    key = None

    # Iterate through each character in the JSON string
    for char in json_str:
        if char == '{':
            stack.append(char)
            current_type = 'dict'
            current_value = {}
        elif char == '[':
            stack.append(char)
            current_type = 'list'
            current_value = []
        elif char == '"':
            if stack[-1] == '"':
                stack.pop()
                if current_type == 'dict':
                    key = current_value
                    current_value = None
                elif current_type == 'list':
                    current_value.append(current_value)
                    current_value = None
            else:
                stack.append(char)
                current_type = 'string'
                current_value = ''
        elif char == ',':
            if current_type == 'dict':
                if key is not None:
                    current_value[key] = current_value
                    key = None
                    current_value = None
            elif current_type == 'list':
                current_value.append(current_value)
                current_value = None
        elif char == '}':
            if current_type == 'dict':
                if key is not None:
                    current_value[key] = current_value
                    key = None
                    current_value = None
                stack.pop()
            elif current_type == 'list':
                stack.pop()
        elif char == ']':
            if current_type == 'list':
                if key is not None:
                    current_value[key] = current_value
                    key = None
                    current_value = None
                stack.pop()
            elif current_type == 'dict':
                stack.pop()
        elif char.isdigit() or char == '-':
            if current_type == 'number':
                current_value += char
            else:
                current_value = char
                current_type = 'number'
        elif char == '.':
            if current_type == 'number':
                current_value += char
            else:
                current_value = char
                current_type = 'number'
        elif char == 'T' or char == 't':
            if current_type == 'boolean':
                current_value = True
            else:
                current_value = 't'
                current_type = 'boolean'
        elif char == 'F' or char == 'f':
            if current_type == 'boolean':
                current_value = False
            else:
                current_value = 'f'
                current_type = 'boolean'
        elif char == ' ' or char == '\n' or char == '\t':
            continue
        else:
            raise ValueError("Invalid JSON character: {}".format(char))

    # If the stack is not empty, it means there are unmatched opening characters
    if stack:
        raise SyntaxError("Unmatched opening character")

    return current_value

