    # Remove leading and trailing whitespace
    json_str = json_str.strip()

    # Check if the JSON string starts with a valid JSON object or array
    if json_str[0] in ('{', '['):
        # Remove the opening bracket or brace
        json_str = json_str[1:]

        # Check if the JSON string ends with a valid JSON object or array
        if json_str[-1] in ('}', ']'):
            # Remove the closing bracket or brace
            json_str = json_str[:-1]

            # Parse the JSON string
            if json_str[0] == '{':
                return parse_object(json_str)
            else:
                return parse_array(json_str)
        else:
            raise ValueError("Invalid JSON structure")
