    parsed_dict = {}
    for pair in pairs:
        key, value = pair.split(':')
        key = key.strip()
        value = value.strip()

        # Parse value
        parsed_dict[key] = parse_value(value)

    # Remove the trailing '}'
    json_str = json_str[:-1]

